-- SpiritualGym: a full year of daily words (365 days), each with a KJV verse, reflection, declaration and prayer
-- Also: daily-word and reading-plan notifications, weekly header pictures, payment settings

ALTER TABLE devotions ADD COLUMN prayer TEXT;
-- Morning "Today's word" notification and daily reading-plan nudge (local time, NULL = off)
ALTER TABLE profiles ADD COLUMN word_time TEXT DEFAULT '06:00';
ALTER TABLE profiles ADD COLUMN plan_time TEXT DEFAULT '07:00';
ALTER TABLE profiles ADD COLUMN last_word_day TEXT;
ALTER TABLE profiles ADD COLUMN last_plan_day TEXT;

-- Payment keys typed into Admin → Payments (only admins can read or change them)
CREATE TABLE secure_settings (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
-- Test gifts are kept apart from real ones
ALTER TABLE donations ADD COLUMN mode TEXT NOT NULL DEFAULT 'live';

-- Header pictures uploaded in Admin → Header pictures (one per week, in rotation). Without any, the app draws its own weekly scene.
CREATE TABLE header_images (
  id         TEXT PRIMARY KEY,
  media_key  TEXT NOT NULL,
  caption    TEXT,
  sort       INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

DELETE FROM devotions;
-- sort = day of the year (1 = 1 January … 365 = 31 December)
